Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#define FOR(i,a,b) for(int i=a;i<=b;i++)
#define FORD(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAXN=262144;

int L,n,k,Mo,len,bit[20],fac[MAXN],inv[MAXN],cnt[MAXN],g[20][MAXN],f[20][MAXN];

int pwr(int x,int y) {
	int res=1;
	while(y) {
		if (y&1) res=(ll)res*x%Mo;
		x=(ll)x*x%Mo;
		y>>=1;
	}
	return res;
}

void add(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void FWT(int *a,int len) {
	for(int step=1;step<len;step<<=1) {
		for(int j=0;j<len;j+=step<<1) {
			for(int k=0;k<step;k++) {
				add(a[j+k+step],a[j+k]);
			}
		}
	}
}
void IFWT(int *a,int len) {
	for(int step=1;step<len;step<<=1) {
		for(int j=0;j<len;j+=step<<1) {
			for(int k=0;k<step;k++) {
				sub(a[j+k+step],a[j+k]);
			}
		}
	}
}

ll h[20],p[20];

void get_ln() {
	p[0]=0;
	FOR(i,1,n) {
		p[i]=h[i]*i;
		FOR(j,1,i-1) p[i]-=p[j]*h[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	FOR(i,0,n) h[i]=(p[i]+Mo)%Mo;
}

void get_exp() {
	p[0]=1;
	FOR(i,1,n) {
		p[i]=0;
		FOR(j,1,i) {
			p[i]+=h[j]*p[i-j]%Mo*j;
		}
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	FOR(i,0,n) h[i]=p[i];
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=pwr(k,L);
	if (L&1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; FOR(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=pwr(fac[L],Mo-2);
	FORD(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	FOR(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	FOR(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	FOR(i,0,len-1) {
		int s=0;
		FOR(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	FOR(i,2,n) inv[i]=(ll)(Mo-Mo/i)*inv[Mo%i]%Mo;
	FOR(i,0,n) FWT(g[i],len);
	FOR(s,0,len-1) {
		FOR(i,0,n) h[i]=g[i][s];
		get_ln();
		FOR(i,0,n) h[i]=h[i]*k;
		get_exp();
		FOR(i,0,n) f[i][s]=h[i];
	}
	IFWT(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
